 [STAThread]static int Main(string[] args){int code=1;var desktop=CreateDesktop("PrimeRemoteTest"+Guid.NewGuid().ToString("N"),IntPtr.Zero,IntPtr.Zero,0,0x10000000,IntPtr.Zero);var thread=new System.Threading.Thread(()=>{try{if(desktop==IntPtr.Zero||!SetThreadDesktop(desktop))throw new Exception("Desktop de teste indisponível");var settings=new Settings{server="https://127.0.0.1:3443",fingerprint=new string('0',64),token=new string('0',64),stationName="Teste"};using(var c=new ClientForm(settings,true)){F("applyPolicies").SetValue(c,new Action<Settings>(x=>{}));F("restorePolicies").SetValue(c,new Action<Settings>(x=>{}));F("saveSettings").SetValue(c,new Action<Settings>(x=>{}));var fake=new Fake(settings);F("transport").SetValue(c,fake);int closed=0,powered=0;F("remoteClose").SetValue(c,new Func<int,string,string>((pid,start)=>{closed++;return "Fechado";}));F("remotePower").SetValue(c,new Action<string>(type=>{if(fake.Finished!=1)throw new Exception("Energia antes do fim da sessão");powered++;}));Invoke(c,"Apply",State(true,false,true,false));if(!(bool)F("locked").GetValue(c))throw new Exception("Bloqueio remoto ignorado");Invoke(c,"Apply",State(true,false,false,true));if((bool)F("locked").GetValue(c))throw new Exception("Desbloqueio ignorado");var bar=(SessionBar)F("timerWindow").GetValue(c);if(!bar.MemberLabel.Text.Contains("TELA VISÍVEL"))throw new Exception("Aviso de visualização ausente");Func<string,string,string,Dictionary<string,object>> command=(id,type,session)=>Files.Json.Deserialize<Dictionary<string,object>>("{\"remote\":{\"commands\":[{\"id\":\""+id+"\",\"type\":\""+type+"\",\"sessionId\":\""+session+"\",\"pid\":42,\"started\":\"638800000000000000\"}]}}");Invoke(c,"HandleRemote",command("1","close","other"));if(closed!=0)throw new Exception("Comando de outra sessão executado");Invoke(c,"HandleRemote",command("2","close","session"));Invoke(c,"HandleRemote",command("2","close","session"));if(closed!=1)throw new Exception("Comando duplicado");Invoke(c,"HandleRemote",command("3","restart","session"));if(powered!=1||fake.Finished!=1)throw new Exception("Fluxo de reinício inválido");Invoke(c,"Apply",State(false,true,false,false));Invoke(c,"HandleRemote",command("4","shutdown",""));if(powered!=1)throw new Exception("Comando durante administração");var remote=new RemoteControl();remote.SetSession("test");bool refused=false;using(var p=System.Diagnostics.Process.GetCurrentProcess()){try{remote.CloseApplication(p.Id,p.StartTime.ToUniversalTime().Ticks.ToString());}catch{refused=true;}}if(!refused)throw new Exception("Próprio cliente exposto ao fechamento");F("allowedExit").SetValue(c,true);c.Close();}File.WriteAllText(args[0],"PASS: bloqueio, desbloqueio, aviso de tela, sessão vinculada, execução única, encerramento antes da energia, administração protegida e próprio processo excluído. Ações Windows simuladas; nenhuma máquina reiniciada.");code=0;}catch(Exception e){File.WriteAllText(args[0],e.ToString());}});thread.SetApartmentState(System.Threading.ApartmentState.STA);thread.Start();thread.Join();return code;}
